    "review.paige-ai.small.private.practice.pathology.groups": "Kleine Privatpraxis-Pathologiegruppen",
    "review.paige-ai.laboratories.without.digital.pathology.scanners": "Laboratorien ohne digitale Pathologie-Scanner",
