function getPaigeAiTranslation(key, lang) {
    return (paigeaiTranslations[lang] && paigeaiTranslations[lang][key]) ||
           (paigeaiTranslations.en && paigeaiTranslations.en[key]) || null;
}

function applyPaigeAiTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.paige-ai.") || key.startsWith("review.common."))) {
            const translation = getPaigeAiTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} paige-ai translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyPaigeAiTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyPaigeAiTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyPaigeAiTranslations(window.i18n?.getCurrentLanguage() || "en");
}
